<?php
 namespace Pterodactyl\Services\Dezerx; use Illuminate\Http\Request; use Illuminate\Support\Str; use Illuminate\Validation\ValidationException; class Uploads { private const MAX_KB = 8192; private const EXTENSIONS = [ 'image/png' => 'png', 'image/jpeg' => 'jpg', 'image/webp' => 'webp', 'image/gif' => 'gif', 'image/svg+xml' => 'svg', 'image/vnd.microsoft.icon' => 'ico', 'image/x-icon' => 'ico', ]; public static function store(Request $request, string $folder): string { $limit = self::limitKb(); if ($request->file('file') === null && (int) $request->server('CONTENT_LENGTH') > $limit * 1024) { throw ValidationException::withMessages([ 'file' => sprintf( 'That image is larger than this panel accepts (%s). Raise upload_max_filesize and post_max_size in php.ini and reload PHP-FPM, or shrink the image.', self::human($limit), ), ]); } $request->validate([ 'file' => ['required', 'file', 'max:' . $limit, 'mimetypes:' . implode(',', array_keys(self::EXTENSIONS))], ], [ 'file.max' => 'That image is larger than this panel accepts (' . self::human($limit) . ').', 'file.mimetypes' => 'That is not an image this panel can use. PNG, JPEG, WebP, GIF, SVG and ICO are accepted.', ]); $file = $request->file('file'); $extension = self::EXTENSIONS[$file->getMimeType()] ?? 'png'; $name = Str::lower(Str::random(24)) . '.' . $extension; $directory = public_path('dezerx/uploads/' . $folder); if (!is_dir($directory)) { mkdir($directory, 0o755, true); } $file->move($directory, $name); return '/dezerx/uploads/' . $folder . '/' . $name; } public static function limitKb(): int { $limits = [self::MAX_KB]; foreach (['upload_max_filesize', 'post_max_size'] as $setting) { $bytes = self::bytes((string) ini_get($setting)); if ($bytes > 0) { $limits[] = intdiv($bytes, 1024); } } return max(1, min($limits)); } private static function bytes(string $value): int { $value = trim($value); if ($value === '') { return 0; } $number = (int) $value; return match (strtolower(substr($value, -1))) { 'g' => $number * 1024 * 1024 * 1024, 'm' => $number * 1024 * 1024, 'k' => $number * 1024, default => $number, }; } private static function human(int $kb): string { return $kb >= 1024 ? rtrim(rtrim(number_format($kb / 1024, 1, '.', ''), '0'), '.') . ' MB' : $kb . ' KB'; } } 